const releaseReadyWorkflowSuccessors = `-- name: ReleaseReadyWorkflowSuccessors :many
UPDATE workflow_node successor
SET state = CASE
        WHEN successor.executor_kind = 'human_gate' THEN 'waiting_human'
        ELSE 'ready'
    END,
    ready_at = CASE
        WHEN successor.executor_kind = 'human_gate' THEN successor.ready_at
        ELSE now()
    END,
    stealable_at = CASE
        WHEN successor.executor_kind = 'agent'
        THEN now() + make_interval(secs => pool.affinity_grace_seconds)
        ELSE successor.stealable_at
    END,
    preferred_daemon_id = COALESCE(successor.preferred_daemon_id, completed.preferred_daemon_id),
    updated_at = now()
FROM workflow_node completed
LEFT JOIN runtime_pool pool ON pool.id = successor.runtime_pool_id
WHERE completed.id = $1
  AND successor.run_id = completed.run_id
  AND successor.state = 'pending'
  AND EXISTS (
      SELECT 1
      FROM workflow_node_dependency direct_edge
      WHERE direct_edge.node_id = successor.id
        AND direct_edge.depends_on_node_id = completed.id
  )
  AND NOT EXISTS (
      SELECT 1
      FROM workflow_node_dependency dependency
      JOIN workflow_node predecessor ON predecessor.id = dependency.depends_on_node_id
      WHERE dependency.node_id = successor.id
        AND predecessor.state <> 'completed'
  )
RETURNING successor.id, successor.run_id, successor.issue_id, successor.passage_key, successor.node_key, successor.generation, successor.executor_kind, successor.agent_id, successor.runtime_pool_id, successor.state, successor.priority, successor.preferred_daemon_id, successor.stealable_at, successor.claim_epoch, successor.current_attempt_id, successor.input_digest, successor.law_digest, successor.output_contract, successor.max_attempts, successor.ready_at, successor.started_at, successor.completed_at, successor.created_at, successor.updated_at
`

